-- ---------- 3. 博客文章（6 条）----------
INSERT INTO `posts` (`slug`, `title`, `excerpt`, `content`, `icon`, `tags`, `author`, `date`, `published`) VALUES ('welcome-to-8bitgo', '欢迎来到 8BitGo：一个在浏览器里玩老游戏的地方', '为什么要做这个站、它现在能做什么，以及接下来打算做什么。', '## 为什么做这个站\n\n小时候玩过的那些游戏，很多人现在想再玩一遍，却卡在第一步：找模拟器、配核心、找 ROM、调手柄。我们想把这些步骤都收起来，让「想玩」到「玩上」之间只隔一次点击。\n\n## 现在能做什么\n\n- 浏览器里直接运行红白机、超任、GBA、PS1、N64、街机等平台的模拟器，不需要安装任何东西\n- 上传自己备份的 ROM，文件只在本地读取，不会经过服务器\n- 即时存档、读档，支持键盘、触屏虚拟按键和蓝牙手柄\n- 注册账号后可以收藏游戏、累积 G 币\n\n## 接下来\n\n联机对战和直播正在开发中，做好后会在这里发公告。有任何建议，欢迎到「玩家社区」里找我们聊。', '🕹️', '[\"站点公告\"]', '8BitGo 团队', '2026-08-20', 1)
  ON DUPLICATE KEY UPDATE `title`=VALUES(`title`), `excerpt`=VALUES(`excerpt`), `content`=VALUES(`content`), `icon`=VALUES(`icon`), `tags`=VALUES(`tags`), `author`=VALUES(`author`), `date`=VALUES(`date`), `published`=VALUES(`published`);
INSERT INTO `posts` (`slug`, `title`, `excerpt`, `content`, `icon`, `tags`, `author`, `date`, `published`) VALUES ('how-browser-emulators-work', '浏览器里的模拟器是怎么跑起来的', '不装软件也能玩主机游戏，靠的是 WebAssembly 和一套叫 EmulatorJS 的开源方案。', '## 先说结论\n\n你在 8BitGo 里看到的游戏画面，是由一段编译成 **WebAssembly** 的模拟器核心在你的浏览器里实时计算出来的。服务器只负责把这段程序发给你，之后所有的运算都发生在本地。\n\n## 三个角色\n\n- **模拟器核心**：负责模仿老主机的 CPU、显卡和声卡。每个平台对应一个核心，例如红白机用的是 FCEUmm，GBA 用的是 mGBA。\n- **EmulatorJS**：把这些核心统一包装成网页组件，提供画面、声音、手柄映射、存档等功能。它是开源项目，8BitGo 直接使用它的官方发行版。\n- **ROM**：游戏本体的数据。核心读取 ROM 后开始执行，就像当年主机读取卡带一样。\n\n## 为什么第一次加载要等几秒\n\n核心文件通常有几 MB，第一次打开某个平台的游戏时需要下载并初始化。之后浏览器会缓存它，再打开同平台的游戏就会快很多。\n\n## 性能够用吗\n\n对于 16 位及以前的主机，现代手机也能满帧运行；PS1 和 N64 更吃性能，建议在电脑上玩，并尽量使用最新版本的 Chrome 或 Safari。', '🧠', '[\"技术\",\"模拟器\"]', '8BitGo 团队', '2026-08-18', 1)
  ON DUPLICATE KEY UPDATE `title`=VALUES(`title`), `excerpt`=VALUES(`excerpt`), `content`=VALUES(`content`), `icon`=VALUES(`icon`), `tags`=VALUES(`tags`), `author`=VALUES(`author`), `date`=VALUES(`date`), `published`=VALUES(`published`);
INSERT INTO `posts` (`slug`, `title`, `excerpt`, `content`, `icon`, `tags`, `author`, `date`, `published`) VALUES ('play-your-own-rom', '新手指南：如何在 8BitGo 玩自己的 ROM', '三步搞定本地 ROM，以及一段关于「什么能玩、什么不能玩」的诚实说明。', '## 三步开始\n\n- 打开页面底部的「玩本地 ROM」，选择 ROM 所属的平台\n- 把文件拖进播放器，或点击按钮选择文件（支持 zip 压缩包）\n- 等待核心加载完成，游戏会自动开始\n\n## 文件去哪了\n\n不去任何地方。文件通过浏览器的本地 API 读取，直接交给运行在页面里的模拟器，全程不上传。关掉页面之后它也就不存在了，下次想玩需要重新选择。\n\n## 关于合法性\n\n模拟器本身是合法的开源软件，但游戏 ROM 受版权保护。请只运行你自己从合法拥有的卡带上备份的文件，或者自制、开源的 ROM。8BitGo 不提供也不索引任何受版权保护的游戏文件。\n\n## 常见问题\n\n- **提示格式不支持**：确认选对了平台，每个平台接受的后缀会显示在播放器里\n- **黑屏没声音**：先点一下游戏画面，浏览器需要用户交互后才允许播放声音\n- **PS1 游戏加载失败**：多轨光盘需要 cue + bin 一起打包成 zip', '📂', '[\"教程\"]', '8BitGo 团队', '2026-08-15', 1)
  ON DUPLICATE KEY UPDATE `title`=VALUES(`title`), `excerpt`=VALUES(`excerpt`), `content`=VALUES(`content`), `icon`=VALUES(`icon`), `tags`=VALUES(`tags`), `author`=VALUES(`author`), `date`=VALUES(`date`), `published`=VALUES(`published`);
INSERT INTO `posts` (`slug`, `title`, `excerpt`, `content`, `icon`, `tags`, `author`, `date`, `published`) VALUES ('why-8bit-graphics-look-like-that', '为什么老游戏的画面那么有辨识度', '有限的调色板、小得可怜的显存，反而逼出了一种至今仍在被模仿的美术风格。', '## 限制造就风格\n\n红白机一次只能在屏幕上显示 25 种颜色，每个 8×8 的图块最多用 3 种颜色加一个透明色。设计师没有办法用渐变或细节堆砌，只能靠轮廓和对比度让角色被一眼认出来。\n\n## 几个有意思的细节\n\n- 马力欧戴帽子、留胡子，是因为像素太少画不出头发和嘴\n- 很多游戏的背景「重复」得很明显，是因为显存只够存一小组图块，靠拼接铺满整个屏幕\n- 角色闪烁并不是特效，而是同一行像素上精灵数量超过硬件上限时的无奈之举\n\n## 今天为什么还在用\n\n限制消失之后，像素风并没有跟着消失。它加载快、辨识度高，也自带一种「游戏感」。8BitGo 的界面用像素字体，也是想把这种感觉延续下来。', '🎨', '[\"复古\",\"闲聊\"]', '像素老张', '2026-08-10', 1)
  ON DUPLICATE KEY UPDATE `title`=VALUES(`title`), `excerpt`=VALUES(`excerpt`), `content`=VALUES(`content`), `icon`=VALUES(`icon`), `tags`=VALUES(`tags`), `author`=VALUES(`author`), `date`=VALUES(`date`), `published`=VALUES(`published`);
INSERT INTO `posts` (`slug`, `title`, `excerpt`, `content`, `icon`, `tags`, `author`, `date`, `published`) VALUES ('five-tips-save-states-and-gamepads', '存档、读档与手柄：把体验拉满的 5 个小技巧', '模拟器比当年的主机多出了不少能力，善用它们会轻松很多。', '## 1. 随时存档\n\n模拟器菜单里的「保存状态」会把当前一瞬间完整记录下来，不依赖游戏自己的存档点。Boss 战前存一下，失败了直接读回来。\n\n## 2. 存档放在浏览器里\n\n即时存档默认保存在浏览器本地。清理站点数据会一起清掉，重要的存档记得用菜单里的导出功能备份成文件。\n\n## 3. 连接手柄\n\n蓝牙或有线手柄连上电脑后，在游戏页面按任意键，模拟器就会识别。默认映射可以在设置里调整，也可以为每个平台分别保存。\n\n## 4. 手机横屏\n\n手机上把屏幕转成横向，虚拟按键会自动铺开，画面也会更大。\n\n## 5. 沉浸模式\n\n游戏页面右下角的「沉浸模式」会收起侧边栏和顶栏，只留画面；按 Esc 退出。想要真正的全屏，用旁边的「全屏」按钮。', '💾', '[\"教程\",\"技巧\"]', '8BitGo 团队', '2026-08-05', 1)
  ON DUPLICATE KEY UPDATE `title`=VALUES(`title`), `excerpt`=VALUES(`excerpt`), `content`=VALUES(`content`), `icon`=VALUES(`icon`), `tags`=VALUES(`tags`), `author`=VALUES(`author`), `date`=VALUES(`date`), `published`=VALUES(`published`);
INSERT INTO `posts` (`slug`, `title`, `excerpt`, `content`, `icon`, `tags`, `author`, `date`, `published`) VALUES ('changelog-2026-08', '更新日志：像素字体、后台管理与随机游戏按钮', '这两周站点做了不少改动，这里集中说一下。', '## 界面\n\n- 全站换成仪表盘式布局：左侧导航栏可折叠，顶部是搜索和快捷入口\n- 中英文都改用像素字体（Geist Pixel + 方舟像素字体）\n- 侧边栏顶部新增「随机玩一个游戏」，不知道玩什么的时候点一下\n\n## 功能\n\n- 游戏详情页支持沉浸模式\n- 新增用户系统：注册后可以收藏游戏、查看最近浏览、累积 G 币\n- 新增博客，就是你现在看到的这个\n\n## 暂时收起\n\n联机玩和直播还在开发中，导航里先标为 coming soon。', '📝', '[\"站点公告\",\"更新日志\"]', '8BitGo 团队', '2026-08-26', 1)
  ON DUPLICATE KEY UPDATE `title`=VALUES(`title`), `excerpt`=VALUES(`excerpt`), `content`=VALUES(`content`), `icon`=VALUES(`icon`), `tags`=VALUES(`tags`), `author`=VALUES(`author`), `date`=VALUES(`date`), `published`=VALUES(`published`);

-- ---------- 4. 管理员账号 ----------
-- 管理员不在此脚本创建（需要密码哈希）。两种方式二选一：
--   A) 在网站上正常注册一个账号，然后在 DBGate 执行（把邮箱换成你的）：
--      UPDATE users SET role='admin' WHERE email='you@example.com';
--   B) 在服务器上：server/.env 填 ADMIN_EMAIL / ADMIN_PASSWORD，然后 `npm run seed`。

-- 完成。可执行以下语句自检：
SELECT 'games' AS t, COUNT(*) AS n FROM games
UNION ALL SELECT 'posts', COUNT(*) FROM posts
UNION ALL SELECT 'users', COUNT(*) FROM users;
